def attach_particle(word: str, particle: str) -> str:
    def has_batchim(char: str) -> bool:
        """Check if a Hangul character has a final consonant (batchim)."""
        if not char:
            return False
        code = ord(char)
        # Hangul syllables: U+AC00 to U+D7A3
        if 0xAC00 <= code <= 0xD7A3:
            # Each syllable: (initial * 588) + (medial * 28) + final
            # final ranges from 0 to 27, where 0 means no batchim
            final = (code - 0xAC00) % 28
            return final != 0
        return False

    def get_final_index(char: str) -> int:
        """Get the final consonant index (0-27) for a Hangul character."""
        if not char:
            return 0
        code = ord(char)
        if 0xAC00 <= code <= 0xD7A3:
            return (code - 0xAC00) % 28
        return 0

    def digit_to_sino_korean(digit_str: str) -> str:
        """Convert a digit string to Sino-Korean number words."""
        sino_korean_digits = ['영', '일', '이', '삼', '사', '오', '육', '칠', '팔', '구']
        result = ''
        for digit in digit_str:
            result += sino_korean_digits[int(digit)]
        return result

    # Determine the last character/sound
    if word[-1].isdigit():
        # Convert digits to Sino-Korean and get the last syllable
        sino_korean = digit_to_sino_korean(word)
        last_char = sino_korean[-1]
    else:
        last_char = word[-1]

    # Determine which particle form to use
    particle_forms = particle.split('/')

    # Special handling for "으로/로" with ㄹ batchim
    if particle == "으로/로":
        final_index = get_final_index(last_char)
        # ㄹ is at index 8
        if final_index == 8:
            return word + particle_forms[1]  # Use "로"
        elif has_batchim(last_char) and final_index != 8:
            return word + particle_forms[0]  # Use "으로"
        else:
            return word + particle_forms[1]  # Use "로"
    else:
        # For other particles: check if there's a batchim
        if has_batchim(last_char):
            return word + particle_forms[0]  # Form before slash (with batchim)
        else:
            return word + particle_forms[1]  # Form after slash (without batchim)
